entries[68810] = { ["name"] = "Technik: Glyphe 'Kolossales Schmettern'", ["text"] = "Benötigt Inschriftenkunde (465)\nBenutzen: Lehrt Euch, wie man die Glyphe 'Kolossales Schmettern' schreibt.\nVerkaufspreis:\nGlyphe 'Kolossales Schmettern'\nErhebliche Glyphe\nKlassen: Krieger\nBenötigt Stufe 25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Kolossales Schmettern' wirkt zusätzlich den Effekt der Fähigkeit 'Rüstung zerreißen' auf das Ziel.\nVerkaufspreis:\nBenötigt Leichtes Pergament , Schwarzfahltinte (3)" }
