entries[68823] = { ["name"] = "Gepanzerter Razzashiraptor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren gepanzerten Razzashiraptor oder gibt ihn wieder frei." }
entries[68824] = { ["name"] = "Schneller zulianischer Panther", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen schnellen zulianischen Panther oder gibt ihn wieder frei." }
entries[68825] = { ["name"] = "Drachenfalke der Amani", ["text"] = "Einzigartig\nReittier\nBenötigt Stufe 60\nBenötigt Gekonntes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Drachenfalken der Amani oder gibt ihn wieder frei. Das ist ein Flugreittier." }
