entries[68890] = { ["name"] = "Doppelpack Papierdrachen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Lasst mit Eurem Waisenkind einen Papierdrachen steigen. (30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[68915] = { ["name"] = "Waagschalen des Lebens", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Scales of Life] (1)\nSchmuck\n+575 Ausdauer\nBenötigt Stufe 85\nAnlegen: Speichert bis zu 11228 zusätzliche Gesundheit aus Zaubern, die Euch über Eure maximale Gesundheit hinaus heilen.\nBenutzen: Gibt sofort alle auf den Waagschalen des Lebens angesammelte Gesundheit als Selbstheilung frei. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[68925] = { ["name"] = "Wechselimpulsblitzkondensator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Variable Pulse Lightning Capacitor] (1)\nSchmuck\n+406 Intelligenz\nBenötigt Stufe 85\nAnlegen: Ihr erhaltet eine elektrische Aufladung, wann immer Ihr einen kritischen Zaubertreffer erzielt, was eine Chance verleiht, einen 'Blitzschlag' abzufeuern, der pro gesammelter 'Elektrischer Aufladung' ( 2926 * 0.875) bis ( 2926 * 1.125) Schaden verursacht. Ihr könnt nicht mehr als 10 'Elektrische Aufladungen' ansammeln und könnt nicht mehr als einmal alle 2,5 Sek. eine erhalten. (2.5s Abklingzeit)\nVerkaufspreis:" }
entries[68926] = { ["name"] = "Fänge des Schicksals", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Jaws of Defeat] (1)\nSchmuck\n+383 Intelligenz\nBenötigt Stufe 85\nBenutzen: Die nächsten 10 Zauber, die innerhalb der nächsten 20 Sek. gewirkt werden, verringern die Kosten Eurer Heilig- und Naturzauber um 110 . Bis zu 10-mal stapelbar. (900ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[68927] = { ["name"] = "Der Hungerleider", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [The Hungerer] (1)\nSchmuck\n+383 Beweglichkeit\nBenötigt Stufe 85\nAnlegen: Eure Nahkampf- und Distanzangriffe gewähren eine Chance, Euer Tempo 15 Sek. lang um 1532 zu erhöhen. (1Min. Abklingzeit)\nVerkaufspreis:" }
