entries[68972] = { ["name"] = "Apparat von Khaz'goroth", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar: [Apparatus of Khaz'goroth] (1)\nSchmuck\n+383 Stärke\nBenötigt Stufe 85\nAnlegen: Eure kritischen Nahkampftreffer gewähren Euch Titanische Kraft, mit der Ihr diesen Apparat betreiben könnt. Die Titanische Kraft ist bis zu 5-mal stapelbar und hält 30 Sek. lang an.\nBenutzen: Zehrt sämtliche Titanische Kraft auf, um Euren kritischen Trefferwert, Euer Tempo oder Eure Meisterschaft pro angesammelter Titanischer Kraft um 510 zu erhöhen. Hält 15 Sek. lang an. Der Apparat wird immer den höchsten dieser drei Werte auswählen. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[68981] = { ["name"] = "Spinnenseidenspindel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Spidersilk Spindle] (1)\nSchmuck\nErhöht Eure Meisterschaftswertung um + 383.\nBenötigt Stufe 85\nAnlegen: Nahkampfangriffe, die Eure Gesundheit unter 35% fallenlassen, verleihen Euch einen Schutzschild, der 30 Sek. lang 17095 Schaden absorbiert. Kann nicht öfter als ein Mal pro Minute auftreten. (1Min. Abklingzeit)\nVerkaufspreis:" }
